  "settings.modelProvider.help.contextWindow": "De contextcapaciteit die het model in één keer kan verwerken, in tokens. ZAICODE gebruikt dit om de context te beheren.\nOverschrijd de werkelijke limiet van het model niet.",
  "settings.modelProvider.help.maxOutputTokens": "Het maximale aantal tokens dat één modelaanvraag kan genereren.\nOverschrijd de werkelijke limiet van het model niet.",
  "settings.modelProvider.help.inputModalities": "Stel de contenttypes in die het model kan ontvangen:\n\n- **Tekst**: Ontvangt tekstinhoud. Verplicht.\n- **Afbeeldingen**: Ontvangt afbeeldingsinhoud.\n- **Video**: Ontvangt video-inhoud.\n- **PDF**: Ontvangt rechtstreeks PDF-documenten.",
  "settings.modelProvider.help.outputModalities": "Het contenttype van de reacties van het model. Alleen tekst wordt momenteel ondersteund.",
  "settings.modelProvider.help.capabilities": "- **Gestructureerde uitvoer**: Ondersteunt JSON Schema-beperkingen voor uitvoervelden, -typen en -structuur.\n- **Ingebouwd webzoeken**: Ondersteunt de ingebouwde webzoekfunctie van de model-API.\n- **Systeemberichten tijdens de conversatie**: Ondersteunt het invoegen van systeeminstructies tijdens een conversatie.\n\nSchakel geen mogelijkheden in die het model niet ondersteunt.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Stel de redeneerniveaus in die beschikbaar zijn in de chat. **Ze moeten van laag naar hoge redeneerinspanning geordend zijn**.\nConfigureer geen redeneerniveaus die het model niet ondersteunt.",
  "settings.modelProvider.help.reasoningLevelMapping": "Gebruik een CEL-expressie om het huidige redeneerniveau, `reasoningLevel`, te koppelen aan velden van de model-API-aanvraag. Het JSON-object dat de expressie retourneert wordt samengevoegd met de body van de uitgaande aanvraag.",
  "settings.modelProvider.help.advanced": "**MFJS tool schema**: Schakelt compatibiliteit met Moonshot Flavored JSON Schema in, veelgebruikt door de Kimi-model-API van Moonshot. Schakel dit alleen in als de model-API dit formaat vereist.",
  "settings.modelProvider.help.followRecommendedConfig": "Komt overeen met de aanbevolen configuratie op basis van model-ID, basis-URL en API-formaat. ZAICODE werkt de aanbevelingen continu bij en synchroniseert ze automatisch met je instellingen.\nAls je een instelling handmatig wijzigt, wordt die instelling handmatig beheerd en volgt ze geen aanbevelingsupdates meer; de overige instellingen blijven beheerd door slimme configuratie.",
